#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"

/* Tunable tile size for the j-dimension update in kernel_lu.
   Can be overridden at compile time, e.g.:
     gcc -O3 -DNDEBUG -DLU_BLOCK_J=128 ...
*/
#ifndef LU_BLOCK_J
# define LU_BLOCK_J 64
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Use a restrict-qualified alias to help the compiler with alias analysis. */
  DATA_TYPE (*restrict a)[n] = A;

  /* Initial lower-triangular matrix with unit diagonal. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *Ai = a[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++)
	Ai[j] = 0;

      Ai[i] = 1;
    }

  /* Make the matrix positive semi-definite.
     Not necessary for LU, but kept for compatibility with the
     original benchmark and the Cholesky variant. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*restrict b)[n] = POLYBENCH_ARRAY(B);

  /* Initialize B to zero. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *Br = b[r];
      for (s = 0; s < n; ++s)
	Br[s] = 0;
    }

  /* Compute B = A * A^T.
     Loop order (t, r, s) is preserved, but we hoist A[r][t]
     into a scalar to reduce repeated loads. */
  for (t = 0; t < n; ++t)
    {
      for (r = 0; r < n; ++r)
	{
	  const DATA_TYPE Art = a[r][t];
	  DATA_TYPE *restrict Br = b[r];

	  for (s = 0; s < n; ++s)
	    Br[s] += Art * a[s][t];
	}
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict Ar = a[r];
      DATA_TYPE *restrict Br = b[r];

      for (s = 0; s < n; ++s)
	Ar[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   - Use a restrict-qualified local alias for A to improve alias analysis.
   - For the L-part (j < i), accumulate into a scalar before storing
     back to memory (fewer loads/stores, same arithmetic order).
   - For the U-part (j >= i), switch to an outer-product formulation:
       A[i, j..] -= L(i,k) * A[k, j..]
     This gives contiguous accesses in the innermost j-loop, which
     is better for cache and vectorization.
   - Block the j-loop with LU_BLOCK_J for large matrices.
*/
static
void __attribute__((noinline, flatten))
kernel_lu(int n,
	  DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Alias with restrict to aid compiler optimizations. */
  DATA_TYPE (*restrict a)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ai = a[i];

    /* Compute L(i, j) for j < i (unit-lower part stored in A). */
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];

      /* Dot product of row i and column j over k = 0..j-1.
         Arithmetic order over k is preserved, we just keep the
         running value in a register instead of memory. */
      for (k = 0; k < j; k++) {
        sum -= Ai[k] * a[k][j];
      }

      /* Store L(i, j) in-place. */
      Ai[j] = sum / a[j][j];
    }

    /* Update U row: j >= i.
       Original code:
         for (j = i; j < N; j++)
           for (k = 0; k < i; k++)
             A[i][j] -= A[i][k] * A[k][j];

       Here we use an outer-product style:
         for (k = 0; k < i; k++)
           A[i, i..] -= L(i,k) * A[k, i..];

       This improves spatial locality for both Ai[.] and a[k][.].
       We also block the j-loop for cache efficiency. */
    for (k = 0; k < i; k++) {
      const DATA_TYPE Lik = Ai[k];

      for (int jj = i; jj < _PB_N; jj += LU_BLOCK_J) {
        int j_end = jj + LU_BLOCK_J;
        if (j_end > _PB_N)
          j_end = _PB_N;

        DATA_TYPE *restrict Aij = &Ai[jj];
        DATA_TYPE *restrict Ak  = &a[k][jj];

        for (j = jj; j < j_end; j++) {
          *Aij -= Lik * (*Ak);
          ++Aij;
          ++Ak;
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
