#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"

/* --------------------------------------------------------------------
 * Tunable parameters for the optimized kernel.
 *
 * LU_J_BLOCK_SIZE controls the blocking factor used for the inner j-loop
 * in the main LU kernel.  It can be overridden at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DLU_J_BLOCK_SIZE=128 ...
 *
 * Setting LU_J_BLOCK_SIZE to 0 disables blocking and reverts to a
 * single, simple j-loop.
 * ------------------------------------------------------------------*/
#ifndef LU_J_BLOCK_SIZE
# define LU_J_BLOCK_SIZE 64
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;
  int r, s, t;

  /* Local restrict-qualified alias for better alias analysis. */
  DATA_TYPE (*restrict a)[n] = A;

  /* Initial lower-triangular matrix with unit diagonal. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict a_i = a[i];

      for (j = 0; j <= i; j++)
	a_i[j] = (DATA_TYPE)(-j % n) / n + (DATA_TYPE)1;

      for (j = i+1; j < n; j++)
	a_i[j] = (DATA_TYPE)0;

      a_i[i] = (DATA_TYPE)1;
    }

  /* Make the matrix positive semi-definite.
     (Not necessary for LU, but we keep the original behavior from
      PolyBench, using a more cache-friendly implementation of
      B = A * A^T.) */
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Compute B = A * A^T.
     Original code used t–r–s ordering:

        for (t) for (r) for (s)
            B[r][s] += A[r][t] * A[s][t];

     which walks A by *columns* in a row-major layout (poor locality).
     Here we use r–s–t ordering so that the innermost loop traverses
     rows of A contiguously, improving cache behavior, while preserving
     the arithmetic order of the sum over t for each B[r][s]. */
  for (r = 0; r < n; ++r)
    {
      for (s = 0; s < n; ++s)
        {
          DATA_TYPE sum = (DATA_TYPE)0;
          for (t = 0; t < n; ++t)
            {
              sum += a[r][t] * a[s][t];
            }
          (POLYBENCH_ARRAY(B))[r][s] = sum;
        }
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict a_r = a[r];
      for (s = 0; s < n; ++s)
        {
          a_r[s] = (POLYBENCH_ARRAY(B))[r][s];
        }
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Create a restrict-qualified alias to help the compiler reason
     about aliasing and enable better vectorization. */
  DATA_TYPE (*restrict a)[n] = A;

  /* PolyBench uses _PB_N for the (possibly truncated) loop bounds. */
  const int N = _PB_N;

#pragma scop
  for (int i = 0; i < N; i++) {
    DATA_TYPE *restrict a_i = a[i];

    /* ----------------------------------------------------------------
     * 1. Compute the L-part (strictly lower triangular) of row i.
     *
     * Original code:
     *   for (j = 0; j < i; j++) {
     *     for (k = 0; k < j; k++) {
     *       A[i][j] -= A[i][k] * A[k][j];
     *     }
     *     A[i][j] /= A[j][j];
     *   }
     *
     * Here we keep the same arithmetic order per element but accumulate
     * through a local variable 'sum' to reduce loads/stores to memory.
     * ----------------------------------------------------------------*/
    for (int j = 0; j < i; j++) {
      DATA_TYPE sum = a_i[j];

      for (int k = 0; k < j; k++) {
        sum -= a_i[k] * a[k][j];
      }

      sum /= a[j][j];
      a_i[j] = sum;
    }

    /* ----------------------------------------------------------------
     * 2. Compute the U-part (from diagonal to the end of row i).
     *
     * Original code:
     *   for (j = i; j < N; j++) {
     *     for (k = 0; k < i; k++) {
     *       A[i][j] -= A[i][k] * A[k][j];
     *     }
     *   }
     *
     * The (j,k) nest is permutable: each A[i][j] receives contributions
     * from k = 0..i-1 in that order, and there are no cross-j
     * dependences.  We therefore rewrite it as:
     *
     *   for (k = 0; k < i; k++) {
     *     for (j = i; j < N; j++) {
     *       A[i][j] -= A[i][k] * A[k][j];
     *     }
     *   }
     *
     * For each (i,j) element, the sequence of updates with respect to k
     * remains in the same order (k from 0 to i-1), so the arithmetic
     * result is unchanged.  This form is a sequence of rank-1 updates
     * that walks both A[i][j] and A[k][j] contiguously in memory,
     * improving cache behavior.
     *
     * We optionally block the inner j-loop, controlled by
     * LU_J_BLOCK_SIZE, to improve locality on very large problems.
     * ----------------------------------------------------------------*/
    for (int k = 0; k < i; k++) {
      const DATA_TYPE lik = a_i[k];          /* L(i,k) */
      const DATA_TYPE *restrict a_k = a[k];  /* row k of U */

#if LU_J_BLOCK_SIZE > 0
      /* Blocked traversal in j; preserves j-ascending order. */
      for (int jb = i; jb < N; jb += LU_J_BLOCK_SIZE) {
        const int j_end =
          (jb + LU_J_BLOCK_SIZE < N) ? (jb + LU_J_BLOCK_SIZE) : N;

        for (int j = jb; j < j_end; ++j) {
          a_i[j] -= lik * a_k[j];
        }
      }
#else
      /* Simple contiguous traversal in j. */
      for (int j = i; j < N; ++j) {
        a_i[j] -= lik * a_k[j];
      }
#endif
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
