/* -------------------------------------------------------------------------
 * Optional tunable parameters.
 * These can be adjusted at compile time (e.g. -DLU_INIT_BLOCK_T=32) to tune
 * the initialization kernel for a given cache hierarchy without changing
 * the program logic.
