/* Array initialization.
 *
 * Initializes A and then forms a positive semi-definite matrix by computing
 * B = A * A^T and copying B back into A.
 *
 * The core B = A * A^T multiplication is written to improve cache locality
 * by working with row pointers and keeping frequently used values in
 * registers, while preserving the original mathematical computation.
 */
static
void init_array (int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, r, s, t;

  /* Local row-major view with 'restrict' to help the compiler optimize.
     This does not change the layout; it only provides more information
     to the optimizer about aliasing. */
  DATA_TYPE (* restrict A_)[n] = A;

  /* Original lower-triangular initialization with explicit row pointers
     to improve spatial locality and reduce address computation. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE* restrict Ai = A_[i];

      for (j = 0; j <= i; j++)
        Ai[j] = (DATA_TYPE)(-j % n) / n + 1;

      for (j = i + 1; j < n; j++)
        Ai[j] = 0;

      Ai[i] = 1;
    }

  /* Make the matrix positive semi-definite.
     (Not necessary for LU, but kept for compatibility with the original
      PolyBench implementation and with the Cholesky benchmark.)
   */
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Get a row-major view on B through the PolyBench macro. */
  DATA_TYPE (* restrict B_)[n] =
      (DATA_TYPE (*)[n]) (POLYBENCH_ARRAY(B));

  /* Zero B. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE* restrict Br = B_[r];
      for (s = 0; s < n; ++s)
        Br[s] = 0;
    }

  /* Compute B = A * A^T
   *
   *   B[r][s] = sum_t A[r][t] * A[s][t]
   *
   * We keep the accumulation order over 't' identical (0..n-1) for each
   * element B[r][s], but we rewrite the loops using row pointers so that:
   *
   * - A[r][t] and A[s][t] are accessed along rows (unit stride),
   * - B[r][s] lives in a scalar register during its own inner loop.
   *
   * The computation performed is mathematically the same as in
   * the original code.
   */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE* restrict Ar = A_[r];
      DATA_TYPE* restrict Br = B_[r];

      for (s = 0; s < n; ++s)
        {
          DATA_TYPE* restrict As = A_[s];
          DATA_TYPE sum = Br[s]; /* currently zero */

          for (t = 0; t < n; ++t)
            sum += Ar[t] * As[t];

          Br[s] = sum;
        }
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE* restrict Ar = A_[r];
      DATA_TYPE* restrict Br = B_[r];
      for (s = 0; s < n; ++s)
        Ar[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * LU factorization of matrix A in-place without pivoting.
 *
 * The core structure is preserved, but with the following optimizations:
 * - Local row-major view 'A_' with 'restrict' for better alias analysis.
 * - Use of row pointers (Ai, Ak) to reduce address computations.
 * - For the U-part update (j >= i) we interchange the (j,k) loops:
 *     Original: for j ... for k ...
 *     Optimized: for k ... for j ...
 *
 *   This is legal because updates to different A[i][j] elements are
 *   independent, and for each fixed (i,j) the updates are still applied
 *   in ascending k order (0..i-1), identical to the original code.
 *   The new loop order greatly improves spatial locality for A[k][j]
 *   (now accessed row-wise) and enables better vectorization.
 */
static
void __attribute__((flatten, noinline))
kernel_lu(int n,
          DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Row-major restricted view of A. */
  DATA_TYPE (* restrict A_)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE* restrict Ai = A_[i];

    /* Compute L part: A[i][j] for j < i. */
    for (j = 0; j < i; j++) {
      DATA_TYPE Aij = Ai[j];

      /* Aij = Aij - sum_{k=0}^{j-1} A[i][k] * A[k][j] */
      for (k = 0; k < j; k++) {
        DATA_TYPE* restrict Ak = A_[k];
        Aij -= Ai[k] * Ak[j];
      }

      /* Store the finalized L-entry. The division is unchanged and
         still uses A[j][j] as in the original implementation. */
      Ai[j] = Aij / A_[j][j];
    }

    /* Compute U part: A[i][j] for j >= i.
     *
     * Original code:
     *   for (j = i; j < _PB_N; j++)
     *     for (k = 0; k < i; k++)
     *       A[i][j] -= A[i][k] * A[k][j];
     *
     * Optimized (j,k) loop interchange:
     *   for (k = 0; k < i; k++)
     *     for (j = i; j < _PB_N; j++)
     *       A[i][j] -= A[i][k] * A[k][j];
     *
     * For every fixed (i,j), the sequence of subtractions over k
     * remains in ascending order (0..i-1), so the floating-point
     * computation for each element A[i][j] is identical.
     */
    for (k = 0; k < i; k++) {
      DATA_TYPE Lik = Ai[k];
      DATA_TYPE* restrict Ak = A_[k];

      for (j = i; j < _PB_N; j++) {
        Ai[j] -= Lik * Ak[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
