    /* Cache the pointer to the current row to reduce
       address computations and improve locality. */
    DATA_TYPE *restrict Ai = a[i];

    /* ---- Compute L part: columns 0 .. i-1 ----
       Original code:
         for (j = 0; j < i; j++) {
           for (k = 0; k < j; k++)
             A[i][j] -= A[i][k] * A[k][j];
           A[i][j] /= A[j][j];
         }

       Below we keep exactly the same arithmetic order for
       each A[i][j]: k still increases from 0 to j-1, the
       updates are accumulated in a scalar 'sum', and then
       we divide once at the end. This preserves the original
       floating-point semantics for each element. */
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];
      for (k = 0; k < j; k++) {
        sum -= Ai[k] * a[k][j];
      }
      Ai[j] = sum / a[j][j];
    }

    /* ---- Compute U part: columns i .. n-1 ----
       Original code:
         for (j = i; j < _PB_N; j++) {
           for (k = 0; k < i; k++) {
